BEGIN;CREATE TABLE IF NOT EXISTS talent_pool_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,pool text NOT NULL CHECK(pool IN('preferred','network','open')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,professional_id,pool));ALTER TABLE talent_pool_members ENABLE ROW LEVEL SECURITY;ALTER TABLE talent_pool_members FORCE ROW LEVEL SECURITY;CREATE POLICY talent_pool_members_tenant_isolation ON talent_pool_members USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON talent_pool_members TO app_runtime;COMMIT;
